<?php
require_once __DIR__.'/includes/functions.php';require_login();require_once __DIR__.'/config/database.php';$pageTitle='Sales';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$customerId=($_POST['customer_id']??'')!==''?(int)$_POST['customer_id']:null;$payment=$_POST['payment_method']??'Cash';$allowed=['Cash','Mobile Money','Card','Bank Transfer'];if(!in_array($payment,$allowed,true))$payment='Cash';$productIds=$_POST['product_id']??[];$quantities=$_POST['quantity']??[];$items=[];
 foreach($productIds as $i=>$pid){$pid=(int)$pid;$qty=(int)($quantities[$i]??0);if($pid>0&&$qty>0){if(isset($items[$pid]))$items[$pid]+=$qty;else$items[$pid]=$qty;}}
 if(!$items){flash('danger','Select at least one product and enter a quantity greater than zero.');redirect('sales.php');}
 try{$pdo->beginTransaction();$lines=[];$total=0;
  foreach($items as $pid=>$qty){$q=$pdo->prepare('SELECT id,name,sku,selling_price,quantity FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);$p=$q->fetch();if(!$p)throw new RuntimeException('One of the selected products no longer exists.');if((int)$p['quantity']<$qty)throw new RuntimeException('Not enough stock for '.$p['name'].'. Available quantity: '.$p['quantity']);$line=(float)$p['selling_price']*$qty;$lines[]=['product'=>$p,'quantity'=>$qty,'line_total'=>$line];$total+=$line;}
  $invoice='INV-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$q=$pdo->prepare('INSERT INTO sales(invoice_no,customer_id,user_id,total_amount,payment_method) VALUES(?,?,?,?,?)');$q->execute([$invoice,$customerId,$_SESSION['user_id'],$total,$payment]);$saleId=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,quantity,unit_price,line_total) VALUES(?,?,?,?,?)');$upd=$pdo->prepare('UPDATE products SET quantity=quantity-? WHERE id=?');foreach($lines as $line){$p=$line['product'];$ins->execute([$saleId,$p['id'],$line['quantity'],$p['selling_price'],$line['line_total']]);$upd->execute([$line['quantity'],$p['id']]);}$pdo->commit();flash('success','Sale recorded successfully. Stock has been updated.');redirect('sale_view.php?id='.$saleId);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger',$e instanceof RuntimeException?$e->getMessage():'Sale could not be saved. Please check the database.');redirect('sales.php');}
}
$products=$pdo->query('SELECT id,sku,name,selling_price,quantity FROM products WHERE quantity>0 ORDER BY name')->fetchAll();$customers=$pdo->query('SELECT id,full_name FROM customers ORDER BY full_name')->fetchAll();$sales=$pdo->query('SELECT s.*,c.full_name AS customer_name FROM sales s LEFT JOIN customers c ON c.id=s.customer_id ORDER BY s.id DESC LIMIT 50')->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="row"><div class="col-lg-5"><div class="card card-success card-outline"><div class="card-header"><h3 class="card-title"><i class="fas fa-cart-plus mr-1"></i> Create New Sale</h3></div><form method="post" id="sale-form"><div class="card-body"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-group"><label>Customer</label><select name="customer_id" class="form-control"><option value="">Walk-in customer</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['full_name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Payment method</label><select name="payment_method" class="form-control"><option>Cash</option><option>Mobile Money</option><option>Card</option><option>Bank Transfer</option></select></div><hr><div class="d-flex justify-content-between align-items-center mb-2"><strong>Items</strong><button type="button" class="btn btn-sm btn-outline-primary" id="add-sale-row"><i class="fas fa-plus"></i> Add item</button></div><div id="sale-items"><div class="sale-item-row border rounded p-2 mb-2"><div class="form-group mb-2"><label>Product</label><select name="product_id[]" class="form-control product-select" required><option value="">Choose product</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>" data-price="<?=e($p['selling_price'])?>" data-stock="<?=(int)$p['quantity']?>"><?=e($p['name'])?> (<?=e($p['sku'])?>) — <?=money($p['selling_price'])?> TZS · Stock <?=$p['quantity']?></option><?php endforeach;?></select></div><div class="row align-items-end"><div class="col-5"><label>Quantity</label><input type="number" name="quantity[]" min="1" value="1" class="form-control quantity-input" required></div><div class="col-5"><label>Line total</label><div class="form-control bg-light line-total">0.00</div></div><div class="col-2"><button type="button" class="btn btn-outline-danger remove-sale-row" title="Remove item"><i class="fas fa-times"></i></button></div></div></div></div><div class="border-top pt-3 text-right sale-total">Total: TZS <span id="sale-grand-total">0.00</span></div><p class="helper-text mt-2">Stock is checked and reduced only when you save the sale.</p></div><div class="card-footer"><button class="btn btn-success btn-block" type="submit"><i class="fas fa-check mr-1"></i> Save Sale</button></div></form></div><?php if(!$products):?><div class="alert alert-warning">No products with stock are available. Add products and quantities first.</div><?php endif;?></div>
<div class="col-lg-7"><div class="card"><div class="card-header"><h3 class="card-title">Recent Sales</h3></div><div class="card-body table-responsive p-0"><table class="table table-hover"><thead><tr><th>Invoice</th><th>Date</th><th>Customer</th><th>Payment</th><th>Total (TZS)</th><th></th></tr></thead><tbody><?php if(!$sales):?><tr><td colspan="6" class="empty-state">No sales have been recorded.</td></tr><?php else:foreach($sales as $s):?><tr><td><?=e($s['invoice_no'])?></td><td><?=e(date('d/m/Y H:i',strtotime($s['sale_date'])))?></td><td><?=e($s['customer_name']?:'Walk-in')?></td><td><?=e($s['payment_method'])?></td><td><?=money($s['total_amount'])?></td><td><a class="btn btn-xs btn-primary" href="sale_view.php?id=<?=(int)$s['id']?>">View</a></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></div>
<script>
(function(){const products=<?=json_encode(array_map(fn($p)=>['id'=>(int)$p['id'],'sku'=>$p['sku'],'name'=>$p['name'],'price'=>(float)$p['selling_price'],'stock'=>(int)$p['quantity']],$products),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;const holder=document.getElementById('sale-items');const template=holder.querySelector('.sale-item-row');document.getElementById('add-sale-row').addEventListener('click',function(){const row=template.cloneNode(true);row.querySelector('select').value='';row.querySelector('input').value='1';row.querySelector('.line-total').textContent='0.00';holder.appendChild(row);});holder.addEventListener('click',function(e){const btn=e.target.closest('.remove-sale-row');if(btn){const rows=holder.querySelectorAll('.sale-item-row');if(rows.length>1)btn.closest('.sale-item-row').remove();calculateSaleTotal();}});document.getElementById('sale-form').addEventListener('submit',function(e){let valid=true;holder.querySelectorAll('.sale-item-row').forEach(function(row){const select=row.querySelector('select');const qty=row.querySelector('input');const option=select.options[select.selectedIndex];if(!select.value||!qty.value||parseInt(qty.value,10)<1)valid=false;else if(option.dataset.stock && parseInt(qty.value,10)>parseInt(option.dataset.stock,10)){alert('Requested quantity is greater than available stock for '+option.text);valid=false;}});if(!valid){e.preventDefault();alert('Please select a product and valid quantity for each item.');}});})();
</script>
